 const series=Array.from({length:12},(_,index)=>({month:year+'-'+String(index+1).padStart(2,'0'),current:byMonth.get(index+1)?.current??null,previous:byMonth.get(index+1)?.previous??null}));
 const values=series.flatMap(point=>[point.current,point.previous]).filter(Number.isFinite),width=printing?1040:1240,height=printing?190:360,left=82,right=80,top=printing?24:42,bottom=49,plotW=width-left-right,plotH=height-top-bottom;
 if(!values.length)return empty('Comparação mensal indisponível','Os valores dos meses ainda não foram confirmados.');
 const min=Math.min(0,...values),max=Math.max(1,...values),padding=(max-min)*.12,lo=min<0?min-padding:0,hi=max+padding,x=index=>left+index*plotW/11,y=value=>top+(hi-value)/(hi-lo)*plotH;
 const path=key=>{let connected=false;return series.map((point,index)=>{if(!Number.isFinite(point[key])){connected=false;return '';}const result=(connected?'L':'M')+x(index).toFixed(2)+','+y(point[key]).toFixed(2);connected=true;return result;}).join(' ');};
 const compact=value=>new Intl.NumberFormat('pt-BR',{notation:'compact',maximumFractionDigits:1}).format(value);
 const grids=Array.from({length:5},(_,index)=>{const value=lo+(hi-lo)*index/4;return '<line class="gridline" x1="'+left+'" x2="'+(width-right)+'" y1="'+y(value)+'" y2="'+y(value)+'"/><text class="rep-chart-axis" x="'+(left-12)+'" y="'+(y(value)+4)+'" text-anchor="end">'+esc(compact(value))+'</text>';}).join('');
